-- M03 SQL设计稿；2026-09-09；未在数据库执行。MySQL 8.0.16+，须在实际小版本隔离演练。
-- 先读主设计第5/6节。逐阶段执行，错误立即停止；DDL隐式提交，不能整包盲跑。
-- 旧datetime与M01审计保持上海业务时区；明确标UTC的新列仅写UTC值。
SET NAMES utf8mb4;
SET SESSION time_zone = '+08:00';

-- 只读；每项violation_count必须0，审阅结果不能替代生产运行验收。
SELECT 'project_unreviewed_active' AS check_name,COUNT(*) AS violation_count FROM (SELECT 1 FROM res_project WHERE del_flag='0' AND (facts_status<>'READY' OR creator_user_id IS NULL)) q;
SELECT 'project_legacy_active_grant' AS check_name,COUNT(*) AS violation_count FROM (SELECT 1 FROM res_project_member r JOIN res_project t ON t.project_id=r.project_id WHERE t.del_flag='0' AND r.grant_type='LEGACY') q;
SELECT 'project_duplicate_code' AS check_name,COUNT(*) AS violation_count FROM (SELECT 1 FROM res_project WHERE del_flag='0' GROUP BY TRIM(project_code) HAVING COUNT(*)>1) q;
SELECT 'project_grant_review_result' AS check_name,COUNT(*) AS violation_count FROM (SELECT 1 FROM m03_migration_grant_review r LEFT JOIN res_project_member t ON t.project_id=r.target_id AND t.user_id=r.user_id AND t.grant_type=r.decision WHERE r.target_type='PROJECT' AND r.decision IN ('MEMBER','SHARE') AND (t.user_id IS NULL OR NOT (t.expire_date <=> r.expire_date) OR NOT (t.granted_at <=> r.granted_at))) q;
SELECT 'project_grant_count' AS check_name,COUNT(*) AS violation_count FROM (SELECT 1 WHERE (SELECT COUNT(*) FROM res_project_member) <> ((SELECT COUNT(*) FROM m03_bak_20260909_res_project_member b WHERE NOT EXISTS (SELECT 1 FROM m03_migration_grant_review r WHERE r.target_type='PROJECT' AND r.target_id=b.project_id AND r.user_id=b.user_id))+(SELECT COUNT(*) FROM m03_migration_grant_review r WHERE r.target_type='PROJECT' AND r.decision IN ('MEMBER','SHARE')))) q;
SELECT 'batch_unreviewed_active' AS check_name,COUNT(*) AS violation_count FROM (SELECT 1 FROM res_batch WHERE del_flag='0' AND (facts_status<>'READY' OR creator_user_id IS NULL)) q;
SELECT 'batch_legacy_active_grant' AS check_name,COUNT(*) AS violation_count FROM (SELECT 1 FROM res_batch_member r JOIN res_batch t ON t.batch_id=r.batch_id WHERE t.del_flag='0' AND r.grant_type='LEGACY') q;
SELECT 'batch_duplicate_code' AS check_name,COUNT(*) AS violation_count FROM (SELECT 1 FROM res_batch WHERE del_flag='0' GROUP BY project_id,TRIM(batch_code) HAVING COUNT(*)>1) q;
SELECT 'batch_grant_review_result' AS check_name,COUNT(*) AS violation_count FROM (SELECT 1 FROM m03_migration_grant_review r LEFT JOIN res_batch_member t ON t.batch_id=r.target_id AND t.user_id=r.user_id AND t.grant_type=r.decision WHERE r.target_type='BATCH' AND r.decision IN ('MEMBER','SHARE') AND (t.user_id IS NULL OR NOT (t.expire_date <=> r.expire_date) OR NOT (t.granted_at <=> r.granted_at))) q;
SELECT 'batch_grant_count' AS check_name,COUNT(*) AS violation_count FROM (SELECT 1 WHERE (SELECT COUNT(*) FROM res_batch_member) <> ((SELECT COUNT(*) FROM m03_bak_20260909_res_batch_member b WHERE NOT EXISTS (SELECT 1 FROM m03_migration_grant_review r WHERE r.target_type='BATCH' AND r.target_id=b.batch_id AND r.user_id=b.user_id))+(SELECT COUNT(*) FROM m03_migration_grant_review r WHERE r.target_type='BATCH' AND r.decision IN ('MEMBER','SHARE')))) q;
SELECT 'culture_unreviewed_active' AS check_name,COUNT(*) AS violation_count FROM (SELECT 1 FROM res_culture WHERE del_flag='0' AND (facts_status<>'READY' OR creator_user_id IS NULL)) q;
SELECT 'culture_legacy_active_grant' AS check_name,COUNT(*) AS violation_count FROM (SELECT 1 FROM res_culture_member r JOIN res_culture t ON t.culture_id=r.culture_id WHERE t.del_flag='0' AND r.grant_type='LEGACY') q;
SELECT 'culture_duplicate_code' AS check_name,COUNT(*) AS violation_count FROM (SELECT 1 FROM res_culture WHERE del_flag='0' AND (lifecycle_state IS NULL OR lifecycle_state<>'CANCELLED') GROUP BY TRIM(culture_code) HAVING COUNT(*)>1) q;
SELECT 'culture_grant_review_result' AS check_name,COUNT(*) AS violation_count FROM (SELECT 1 FROM m03_migration_grant_review r LEFT JOIN res_culture_member t ON t.culture_id=r.target_id AND t.user_id=r.user_id AND t.grant_type=r.decision WHERE r.target_type='CULTURE' AND r.decision IN ('MEMBER','SHARE') AND (t.user_id IS NULL OR NOT (t.expire_date <=> r.expire_date) OR NOT (t.granted_at <=> r.granted_at))) q;
SELECT 'culture_grant_count' AS check_name,COUNT(*) AS violation_count FROM (SELECT 1 WHERE (SELECT COUNT(*) FROM res_culture_member) <> ((SELECT COUNT(*) FROM m03_bak_20260909_res_culture_member b WHERE NOT EXISTS (SELECT 1 FROM m03_migration_grant_review r WHERE r.target_type='CULTURE' AND r.target_id=b.culture_id AND r.user_id=b.user_id))+(SELECT COUNT(*) FROM m03_migration_grant_review r WHERE r.target_type='CULTURE' AND r.decision IN ('MEMBER','SHARE')))) q;
SELECT 'active_occupancy_mismatch' AS check_name,COUNT(*) AS violation_count FROM (SELECT 1 FROM res_culture c LEFT JOIN res_culture_occupancy o ON o.culture_id=c.culture_id AND o.occupancy_state<>'RELEASED' WHERE c.del_flag='0' AND c.facts_status='READY' AND ((c.lifecycle_state IN ('DRAFT','EXPIRED') AND o.occupancy_id IS NOT NULL) OR (c.lifecycle_state='NOT_STARTED' AND (o.occupancy_id IS NULL OR o.occupancy_state<>'RESERVED')) OR (c.lifecycle_state IN ('RUNNING','DELAYED') AND (o.occupancy_id IS NULL OR o.occupancy_state<>'RUNNING')) OR (c.lifecycle_state IN ('FINISHED','CANCELLED') AND o.occupancy_id IS NOT NULL AND o.occupancy_state<>'RELEASE_PENDING'))) q;
SELECT 'occupancy_identity_mismatch' AS check_name,COUNT(*) AS violation_count FROM (SELECT 1 FROM res_culture_occupancy o LEFT JOIN res_culture c ON c.culture_id=o.culture_id WHERE c.culture_id IS NULL OR (o.occupancy_state<>'RELEASED' AND (c.del_flag<>'0' OR c.device_kind<>o.device_kind OR c.device_id<>o.device_id OR c.lab_id<>o.lab_id))) q;
SELECT 'culture_setup_mismatch' AS check_name,COUNT(*) AS violation_count FROM (SELECT 1 FROM res_culture c JOIN res_culture_member r ON r.culture_id=c.culture_id AND r.grant_type='MEMBER' WHERE c.del_flag='0' AND c.member_setup_state<>'CONFIGURED') q;
SELECT 'active_culture_parent_mismatch' AS check_name,COUNT(*) AS violation_count FROM (SELECT 1 FROM res_culture c LEFT JOIN res_batch b ON b.batch_id=c.batch_id WHERE c.del_flag='0' AND (b.batch_id IS NULL OR b.del_flag<>'0' OR c.project_id<>b.project_id OR c.lab_id<>b.lab_id)) q;
SELECT 'res_project_row_count' AS check_name,(SELECT COUNT(*) FROM `res_project`) AS after_count,(SELECT COUNT(*) FROM `m03_bak_20260909_res_project`) AS before_count;
SELECT 'res_project_leader_row_count' AS check_name,(SELECT COUNT(*) FROM `res_project_leader`) AS after_count,(SELECT COUNT(*) FROM `m03_bak_20260909_res_project_leader`) AS before_count;
SELECT 'res_project_lab_row_count' AS check_name,(SELECT COUNT(*) FROM `res_project_lab`) AS after_count,(SELECT COUNT(*) FROM `m03_bak_20260909_res_project_lab`) AS before_count;
SELECT 'res_project_tag_row_count' AS check_name,(SELECT COUNT(*) FROM `res_project_tag`) AS after_count,(SELECT COUNT(*) FROM `m03_bak_20260909_res_project_tag`) AS before_count;
SELECT 'res_batch_row_count' AS check_name,(SELECT COUNT(*) FROM `res_batch`) AS after_count,(SELECT COUNT(*) FROM `m03_bak_20260909_res_batch`) AS before_count;
SELECT 'res_batch_leader_row_count' AS check_name,(SELECT COUNT(*) FROM `res_batch_leader`) AS after_count,(SELECT COUNT(*) FROM `m03_bak_20260909_res_batch_leader`) AS before_count;
SELECT 'res_culture_row_count' AS check_name,(SELECT COUNT(*) FROM `res_culture`) AS after_count,(SELECT COUNT(*) FROM `m03_bak_20260909_res_culture`) AS before_count;
SELECT 'res_culture_leader_row_count' AS check_name,(SELECT COUNT(*) FROM `res_culture_leader`) AS after_count,(SELECT COUNT(*) FROM `m03_bak_20260909_res_culture_leader`) AS before_count;
SELECT 'project_grants' AS check_name,grant_type,COUNT(*) AS row_count FROM res_project_member GROUP BY grant_type;
SELECT 'batch_grants' AS check_name,grant_type,COUNT(*) AS row_count FROM res_batch_member GROUP BY grant_type;
SELECT 'culture_grants' AS check_name,grant_type,COUNT(*) AS row_count FROM res_culture_member GROUP BY grant_type;
SELECT phase,system_revision_before,system_revision_after FROM m03_migration_run WHERE run_key='M03_20260909';
SELECT COUNT(*) AS migration_generated_notices_must_be_zero FROM res_culture_notice_outbox;
SELECT TABLE_NAME,COLUMN_NAME,GENERATION_EXPRESSION FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND (COLUMN_NAME='m03_live_code' OR (TABLE_NAME='res_culture_occupancy' AND COLUMN_NAME='active_slot'));
SELECT TABLE_NAME,INDEX_NAME,NON_UNIQUE,SEQ_IN_INDEX,COLUMN_NAME FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND INDEX_NAME LIKE '%m03%' ORDER BY TABLE_NAME,INDEX_NAME,SEQ_IN_INDEX;
